-- Prueba confirmada por el propietario el 15/10/2026. Sólo contenido editorial.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('corte-caja-sin-diferencia',$texto$Cerrar caja sin diferencia: de $1,000 a $1,150$texto$,'Finanzas',$texto$Abrir un corte antes de registrar un ingreso de $200 y un egreso de $50, declarar $1,150 y comprobar un cierre sin diferencia, sin modificar nuevamente el saldo de la caja.$texto$,$texto$Usuario administrativo identificado con permisos y alcance sobre institución/plantel, caja activa en MXN y motivos de ingreso/egreso activos. Usar datos de prueba autorizados y una caja aislada, sin movimientos concurrentes. Si ya se terminó el ejemplo CAJA-CORTE-TEST, consultar ese corte cerrado; no volver a capturar los movimientos ni abrir otro corte para reconstruirlo. La guía no ejecuta operaciones ni asigna permisos.$texto$,$texto$El propietario confirmó: saldo inicial $1,000, dos movimientos (folios 1 a 2), ingreso $200, egreso $50, esperado $1,150, declarado $1,150, diferencia $0 y cuenta con saldo actual $1,150. Observaciones: Prueba de cierre sin diferencia. El recorrido siguiente reproduce el caso desde cero únicamente en otra caja de ensayo. Las comprobaciones adicionales de Cancelar modal y exportación se describen como controles recomendados, no como nueva aceptación humana. No hay pagos de alumnos ni transferencias entre cuentas en este ejemplo.$texto$,1,DATE '2026-10-15','CONFIRMADA');

INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CUENTA_FINANCIERA_LEER','CUENTA_FINANCIERA_ADMINISTRAR','MOTIVO_FINANCIERO_LEER','MOTIVO_FINANCIERO_ADMINISTRAR','MOVIMIENTO_FINANCIERO_LEER','MOVIMIENTO_FINANCIERO_REGISTRAR','CORTE_CAJA_LEER','CORTE_CAJA_ADMINISTRAR']) WHERE g.slug='corte-caja-sin-diferencia';

INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('corte-caja-sin-diferencia',1,$texto$Preparar una caja exclusiva con $1,000$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Entra a Administración → Finanzas → Cuentas financieras y busca CAJA-CORTE-TEST → Aplicar filtros. Si corresponde al ensayo ya concluido, consulta sus datos y no vuelvas a generar movimientos. Para una nueva reproducción elige un código diferente, por ejemplo CAJA-CORTE-OTRA. 2. Sólo para reproducir desde cero pulsa Nuevo registro y selecciona institución, plantel del ensayo, tipo CAJA, moneda MXN, código exclusivo y nombre Caja para prueba de corte. 3. Captura Saldo inicial1000.00 y fecha de apertura no futura, anterior o igual a los movimientos que registrarás; conserva Cuenta activa y pulsa Crear cuenta. No cambies una cuenta operativa para simular este saldo. 4. Vuelve al listado, busca el código exacto y comprueba Saldo actual $1,000; anota institución, plantel y cuenta para usarlos en todos los pasos.$texto$,$texto$Caja nueva en MXN: saldo inicial y actual $1,000.00.$texto$,$texto$Cuenta aislada, sin ingresos/egresos todavía.$texto$,$texto$El saldo inicial no es un ingreso del corte. No duplicar la caja ni editar su saldo inicial después de iniciar movimientos.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('corte-caja-sin-diferencia',2,$texto$Preparar los motivos de ingreso y egreso$texto$,$texto$Administración$texto$,$texto$Motivos financieros$texto$,$texto$1. Entra a Administración → Finanzas → Motivos financieros, busca CORTE-ING-TEST → Aplicar filtros; si ya existe, revisa que sea activo, de la institución y naturaleza INGRESO. 2. Si no existe pulsa Nuevo registro: institución del ensayo, código CORTE-ING-TEST, nombre Ingreso de prueba de corte, Naturaleza INGRESO, Categoría Pruebas y Motivo activo → Crear motivo. 3. Repite la consulta para CORTE-EGR-TEST; si hace falta créalo con nombre Egreso de prueba de corte, Naturaleza EGRESO, misma institución, Categoría Pruebas y Motivo activo. 4. Conserva ambos códigos. Son catálogos para clasificar movimientos: crearlos no modifica la caja; no cambies motivos operativos que ya utilizan otros registros.$texto$,$texto$Un motivo INGRESO y otro EGRESO, activos y de la misma institución.$texto$,$texto$Motivos disponibles en el buscador compatible con el tipo seleccionado.$texto$,$texto$Motivo financiero no es Concepto de cobro. Estos movimientos manuales no crean adeudos ni comprobantes de pago de alumnos.$texto$,$texto$/admin/catalogos/motivos-financieros$texto$),
('corte-caja-sin-diferencia',3,$texto$Abrir el corte ANTES de los movimientos$texto$,$texto$Administración$texto$,$texto$Movimientos financieros → Cortes de caja$texto$,$texto$1. Entra a Administración → Finanzas → Movimientos financieros → Cortes de caja. Busca la caja del ensayo y comprueba que no tenga otro corte abierto; si ya está abierto para esta prueba, abre Ver detalle y continúa sin duplicarlo. 2. Para un ensayo nuevo pulsa Abrir corte, selecciona Institución y Cuenta tipo caja desde la ayuda de búsqueda; verifica el código antes de guardar. 3. En Observaciones de apertura captura Prueba de corte con saldo inicial de 1000, ingreso de 200 y egreso de 50 y pulsa Abrir corte. 4. En el detalle verifica Estado ABIERTO, Saldo inicial del sistema $1,000 y observaciones de apertura. Anota el número del corte; deja Conteo físico y cierre sin capturar por ahora.$texto$,$texto$Corte abierto con saldo inicial del sistema $1,000.00.$texto$,$texto$El corte guarda el saldo y último folio existentes al abrirlo.$texto$,$texto$Sólo los movimientos registrados después de abrir integrarán sus ingresos y egresos, por secuencia contable; no basta ponerles una fecha posterior. No abrir otro corte al recargar o volver a iniciar sesión.$texto$,$texto$/admin/cortes-caja/nuevo$texto$),
('corte-caja-sin-diferencia',4,$texto$Registrar el ingreso manual de $200$texto$,$texto$Administración$texto$,$texto$Movimientos financieros → Registrar movimiento$texto$,$texto$1. Entra a Administración → Finanzas → Movimientos financieros y pulsa Registrar movimiento. Selecciona institución y la misma Cuenta financiera del corte abierto; revisa el plantel de operación y captura fecha/hora actual no futura. 2. Elige Tipo INGRESO y en Motivo da foco para ver hasta diez opciones o escribe tres caracteres; selecciona CORTE-ING-TEST de la lista, no dejes sólo texto escrito. Captura Monto200.00. 3. En Detalle comprobable captura Concepto Ingreso manual para prueba de corte y Referencia CORTE-TEST-ING-200; Tercero puede quedar vacío. Pulsa Registrar movimiento, revisa caja/tipo/motivo/monto en el modal y confirma una vez. 4. En Cuentas financieras busca esa misma caja → Aplicar filtros y comprueba Saldo actual $1,200. No registres otro ingreso para repetir la comprobación.$texto$,$texto$$1,000 + $200 = $1,200.$texto$,$texto$Un ingreso de $200 posterior a la apertura.$texto$,$texto$Éste es un movimiento manual de prueba independiente, no el pago200 ya validado de un alumno en otro ensayo. No registrar el mismo dinero dos veces.$texto$,$texto$/admin/movimientos-financieros/nuevo$texto$),
('corte-caja-sin-diferencia',5,$texto$Registrar el egreso manual de $50$texto$,$texto$Administración$texto$,$texto$Movimientos financieros → Registrar movimiento$texto$,$texto$1. Entra a Administración → Finanzas → Movimientos financieros → Registrar movimiento; selecciona nuevamente la misma institución y caja del corte, plantel correspondiente y fecha/hora actual no futura. 2. Elige Tipo EGRESO; la selección anterior de motivo se limpia al cambiar tipo. Busca y selecciona CORTE-EGR-TEST, luego captura Monto50.00. 3. Captura Concepto Salida manual para prueba de corte y Referencia CORTE-TEST-EGR-50; revisa Registrar movimiento → modal → Confirmar y registrar movimiento una sola vez. 4. En Cuentas financieras consulta esa caja → Aplicar filtros: Saldo actual $1,150. En Movimientos financieros filtra por la caja y comprueba un ingreso200 y un egreso50, no dos ingresos.$texto$,$texto$$1,200 - $50 = $1,150.$texto$,$texto$Dos movimientos en el ensayo: ingreso200 y egreso50.$texto$,$texto$Los movimientos publicados no se editan ni borran. Si te equivocas, detén el ejemplo y revisa el flujo de reversión; no fuerces el saldo cambiando el saldo inicial.$texto$,$texto$/admin/movimientos-financieros/nuevo$texto$),
('corte-caja-sin-diferencia',6,$texto$Volver al mismo corte y declarar el efectivo$texto$,$texto$Administración$texto$,$texto$Cortes de caja → Contar y cerrar$texto$,$texto$1. Entra a Administración → Finanzas → Movimientos financieros → Cortes de caja, selecciona la misma caja y Estado ABIERTO → Aplicar filtros; identifica el número guardado al abrir. 2. Pulsa Contar y cerrar de ese registro. El botón abre el detalle; por sí solo no cierra ni registra dinero. Comprueba institución/caja y saldo inicial del sistema1000. 3. En Conteo físico y cierre captura Efectivo declarado1150.00. Deja Justificación de diferencia vacía porque en este caso el conteo coincide. En Observaciones de cierre captura Prueba de cierre sin diferencia. 4. Revisa la captura sin registrar más movimientos. El saldo esperado permanece oculto antes de procesar el cierre, como parte del conteo ciego.$texto$,$texto$Declarado $1,150.00, observaciones Prueba de cierre sin diferencia.$texto$,$texto$Conteo preparado para confirmar en el mismo corte.$texto$,$texto$No captures ingreso1150 ni egreso por el total contado. Declarar efectivo no es una nueva operación financiera.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sin-diferencia',7,$texto$Revisar el modal y, si hace falta, cancelar sin cerrar$texto$,$texto$Administración$texto$,$texto$Detalle del corte → Conciliar y cerrar$texto$,$texto$1. En el detalle del corte abierto con el conteo capturado pulsa Conciliar y cerrar; se abre un modal, todavía no se ejecuta el cierre. 2. Comprueba número de corte, caja, plantel, Efectivo declarado $1,150, justificación y observaciones. El modal no muestra el saldo esperado ni adelanta la diferencia. 3. Como control adicional recomendado, pulsa Cancelar dentro del modal: debe cerrarse conservando los campos y dejando el corte abierto. No confundas Cancelar con Cerrar después, que vuelve al historial sin cerrar y no promete conservar campos sin guardar. 4. Si la captura es correcta pulsa de nuevo Conciliar y cerrar para volver al resumen; corrige antes de confirmar si elegiste otra caja o un importe diferente.$texto$,$texto$Cancelar el modal no publica un cierre ni otro movimiento.$texto$,$texto$Resumen listo; cierre aún no confirmado.$texto$,$texto$Cancelar modal es una comprobación adicional recomendada. No intentes esta acción en el corte histórico ya cerrado ni abras otro sólo para repetirla.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sin-diferencia',8,$texto$Confirmar el cierre sin diferencia$texto$,$texto$Administración$texto$,$texto$Modal → Confirmar y cerrar caja$texto$,$texto$1. En el modal de la captura actual verifica otra vez caja y Efectivo declarado $1,150; confirma con Confirmar y cerrar caja una sola vez y espera la respuesta. 2. Debe aparecer Corte cerrado y conciliado correctamente y el detalle con Estado CERRADO. No vuelvas al formulario antiguo para registrar otro cierre. 3. En Resultado de la conciliación comprueba Saldo esperado al cierre $1,150, Efectivo declarado $1,150 y Diferencia del conteo $0, con explicación Sin diferencia. 4. Revisa Fecha de cierre y Cerrado por, Movimientos incluidos2, Ingresos del corte200, Egresos del corte50 y Observaciones de cierre. En la caja nueva del ensayo confirmado fueron Folios1 a2; otro ensayo puede tener otros folios.$texto$,$texto$Esperado = $1,000 + $200 - $50 = $1,150; diferencia = $1,150 - $1,150 = $0.$texto$,$texto$Corte cerrado, dos movimientos y sin faltante ni sobrante.$texto$,$texto$Cerrar el corte no crea un ingreso o egreso. Si hay diferencia, la justificación es obligatoria; ese escenario se prueba por separado y no debe declararse confirmado con este ejemplo.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sin-diferencia',9,$texto$Leer el historial sin confundir diferencia con saldo$texto$,$texto$Administración$texto$,$texto$Cortes de caja → Historial de conciliaciones$texto$,$texto$1. En el detalle cerrado pulsa Volver al historial. En los filtros selecciona institución, la misma Caja y Estado CERRADO → Aplicar filtros; limita Desde/Hasta si necesitas ubicar la fecha de apertura. 2. Identifica el número del corte: Saldo inicial debe mostrar $1,000 y Diferencia del cierre debe decir Sin diferencia · $0.00; debajo aparece Esperado: $1,150. El cero no significa que la cuenta quedó sin dinero. 3. Pulsa Ver detalle para consultar nuevamente tarjetas, observaciones y autor del cierre. Ver movimientos de la caja abre el libro filtrado por esa cuenta; no modifica el corte. 4. Como comprobación adicional de consulta puedes volver al historial y pulsar Exportar Excel: conserva institución/caja/estado/rango de apertura aplicados. El corte tiene exportación Excel; no busques un botón PDF de corte que no existe.$texto$,$texto$Diferencia del cierre $0 y saldo esperado $1,150 representan datos distintos.$texto$,$texto$Historial legible y consulta trazable del resultado.$texto$,$texto$El libro filtrado por cuenta puede contener movimientos de otros cortes; compara sus folios con los incluidos en este cierre. La exportación es un control recomendado, no una nueva operación.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sin-diferencia',10,$texto$Comprobar el saldo actual y concluir$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Entra a Administración → Finanzas → Cuentas financieras y busca la caja del ensayo → Aplicar filtros; no te quedes sólo con el saldo esperado del corte histórico. 2. Verifica Saldo inicial $1,000 y Saldo actual $1,150; si abres Editar, la ficha también muestra Saldo actual disponible. No modifiques ni guardes datos para consultar esos importes. 3. Si no coincide, revisa en Movimientos financieros los registros posteriores al cierre y su cuenta: el corte conserva una fotografía de su cierre, mientras el saldo actual puede cambiar después por otras operaciones. 4. Si no hubo otros movimientos y coincide1150, la prueba queda concluida. Conserva el corte cerrado y sus dos movimientos sin repetirlos. El propietario confirmó este resultado completo el15/10/2026; la siguiente prueba de faltante1 y la revisión de reportes financieros siguen pendientes.$texto$,$texto$Cuenta con saldo actual $1,150.00; corte cerrado con diferencia $0.00.$texto$,$texto$Caso confirmado de apertura, movimientos, conteo y cierre sin diferencia.$texto$,$texto$No confundir cierre de caja con cierre mensual contable: no bloquea todos los módulos ni meses. Esta guía no confirma aún faltantes, sobrantes, transferencias, retiros ni compras.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;

UPDATE guia_proceso_paso SET precaucion=$texto$No repetir los ensayos de seguridad ya terminados. El corte de caja sin diferencia también está confirmado en su guía Cerrar caja sin diferencia: de $1,000 a $1,150. La prueba de faltante1 y los reportes financieros siguen pendientes por separado.$texto$
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='seguridad-registro-validacion-pagos') AND numero=12;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-15' WHERE slug='seguridad-registro-validacion-pagos';
